// src/assets/fonts/pdfFonts.ts
// Polices embarquées pour l'export PDF (jsPDF), encodées en base64.
//
// Pourquoi embarquer des polices : les 14 polices standard de jsPDF (helvetica, times,
// courier) couvrent l'encodage WinAnsi (Latin-1 étendu), donc les accents français
// courants (é, è, à, ç, «», —) s'affichent déjà correctement avec elles — vérifié
// manuellement avant d'ajouter cet embarquement. On embarque malgré tout Cinzel/Inter
// (polices déjà utilisées dans toute l'app via Tailwind, voir tailwind.config.js et
// index.html) pour que la fiche PDF exportée reste visuellement cohérente avec la
// charte du Bestiaire, plutôt que de retomber sur une police système générique.
//
// Origine des fichiers : polices variables officielles Google Fonts (Inter, Cinzel),
// instanciées en graisses statiques (wght=400/600 pour Inter, 600/700 pour Cinzel) via
// `fonttools varLib.instancer`, puis sous-ensemblées (Latin de base + Latin-1 + Latin
// Extended-A pour œ/Œ + ponctuation typographique «»—…) via `pyftsubset` pour limiter
// la taille de ce module — il n'est chargé que via import() dynamique au moment de
// l'export PDF (voir pdfExport.ts), donc jamais inclus dans le bundle principal.
// Licence : SIL Open Font License 1.1 (Google Fonts).

export const INTER_REGULAR_BASE64 = ""
export const INTER_SEMIBOLD_BASE64 = ""
export const CINZEL_SEMIBOLD_BASE64 = ""
export const CINZEL_BOLD_BASE64 = ""
